import {parse,compute,numberText} from './core.mjs';

const $=id=>document.getElementById(id), state={name:'',createdAt:null,updatedAt:null,files:[],records:{},eis:[],reaction:'HER',equilibriumPotentialV_RHE:0,dirty:false};
const id=prefix=>`${prefix}-${crypto.randomUUID()}`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const dateStamp=()=>{const d=new Date();return `${d.getFullYear()}${String(d.getMonth()+1).padStart(2,'0')}${String(d.getDate()).padStart(2,'0')}`;};
const currentParams=()=>({voltage:Number($('voltage').value),area:Number($('area').value),resistance:Number($('resistance').value)});
function markDirty(){state.dirty=true;}
function setStatus(t){$('project-status').textContent=t;}
function typeFor(file){const n=file.name.toLowerCase();if(!/\.(txt|csv)$/.test(n))return 'other';if(/tafel|处理后|processed|result/.test(n))return 'processed';if(/^eis(?:[-_.]|\.)/.test(n)||/eis/.test(n))return 'eis';if(/^cv(?:[-_.]|\.)/.test(n)||/\bcv\b/.test(n))return 'cv';if(/lsv/.test(n))return 'lsv';return 'other';}
function projectPath(f){return f.relativePath||f.originalName;}
function render(){const body=$('project-files');const active=state.files.filter(f=>!f.deletedAt);if(!active.length){body.innerHTML='<tr><td colspan="5" class="table-empty">项目文件列表为空</td></tr>';$('project-origin').disabled=true;return;}
 body.replaceChildren(...active.map(f=>{const tr=document.createElement('tr'),td0=document.createElement('td'),cb=document.createElement('input');cb.type='checkbox';cb.className='project-check';cb.dataset.id=f.id;cb.checked=f.selected!==false&&f.kind==='lsv';cb.disabled=f.kind!=='lsv';cb.addEventListener('change',()=>{f.selected=cb.checked;markDirty();updateOrigin();});td0.append(cb);const td1=document.createElement('td');td1.className='project-name';td1.innerHTML=`<input class="project-label sample-label" aria-label="样品名称" value="${esc(f.sampleName||'未分组')}"><input class="project-label test-label" aria-label="测试标签" value="${esc(f.testLabel||f.originalName)}"><small>${esc(projectPath(f))}</small>`;td1.querySelector('.sample-label').onchange=e=>{const old=f.sampleId;f.sampleName=e.target.value.trim()||'未分组';const peer=state.files.find(x=>x!==f&&x.sampleId===old);if(!peer||peer.sampleName!==f.sampleName)f.sampleId=id('sample');markDirty();render();};td1.querySelector('.test-label').onchange=e=>{f.testLabel=e.target.value.trim()||f.originalName;markDirty();render();};const td2=document.createElement('td');td2.textContent=({lsv:'LSV 原始',eis:'EIS',cv:'CV',processed:'已有结果',other:'其他'})[f.kind]||f.kind;const td3=document.createElement('td');td3.textContent=f.kind==='lsv'?(state.records[f.id]?.results?.lsv?'已处理':'待处理'):f.kind==='eis'?(f.eisResult?'已分析':'已导入'):'已导入';const td4=document.createElement('td'),open=document.createElement('button'),del=document.createElement('button');open.type=del.type='button';open.className=del.className='secondary';open.textContent=f.kind==='lsv'?'打开':'查看';open.onclick=()=>openFile(f.id);del.textContent='移除';del.onclick=()=>{f.deletedAt=new Date().toISOString();markDirty();render();setStatus('已暂存移除；保存项目时才会从项目文件中删除。');};td4.append(open,del);tr.append(td0,td1,td2,td3,td4);return tr;}));updateOrigin();}
function updateOrigin(){$('project-origin').disabled=!state.files.some(f=>!f.deletedAt&&f.kind==='lsv'&&f.selected!==false&&state.records[f.id]?.results?.lsv);}
function getPayload(){const files=state.files.filter(f=>!f.deletedAt);const ids=new Set(files.map(f=>f.id));return {format:'lsv-project',version:1,project:{name:state.name||'LSV项目',createdAt:state.createdAt||new Date().toISOString(),updatedAt:new Date().toISOString()},samples:[...new Map(files.map(f=>[f.sampleId,{id:f.sampleId,name:f.sampleName}])).values()],files:files.map(({deletedAt,rawText,...f})=>({...f,...(rawText&&f.kind!=='lsv'?{rawText}:{})})),records:Object.fromEntries(Object.entries(state.records).filter(([fileId])=>ids.has(fileId))),eis:state.eis.filter(e=>ids.has(e.fileId)),settings:{reaction:state.reaction,targetCurrentsMa:[10,100,1000],currentTargetBasis:'absolute-current',equilibriumPotentialV_RHE:state.equilibriumPotentialV_RHE,overpotentialFormula:'abs(E_at_target_current - equilibriumPotential)'}};}
function download(blob,name){const a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1500);}
function save(){const payload=getPayload();state.updatedAt=payload.project.updatedAt;const safe=(state.name||'LSV项目').replace(/[\\/:*?"<>|]/g,'_');download(new Blob([JSON.stringify(payload,null,2)],{type:'application/json;charset=utf-8'}),`${safe}_${dateStamp()}.lsvproj`);state.files=state.files.filter(f=>!f.deletedAt);const ids=new Set(state.files.map(f=>f.id));state.records=Object.fromEntries(Object.entries(state.records).filter(([fileId])=>ids.has(fileId)));state.eis=state.eis.filter(e=>ids.has(e.fileId));state.dirty=false;setStatus(`项目已保存：${safe}_${dateStamp()}.lsvproj。浏览器会下载更新版；如需替换旧版，请在下载提示中选择替换或手动整理。`);render();}
function validateProject(p){if(!p||p.format!=='lsv-project'||!Number.isInteger(p.version)||p.version!==1)throw Error('项目格式不受支持或版本不兼容。');if(!Array.isArray(p.files)||!p.records||typeof p.records!=='object')throw Error('项目文件缺少 files 或 records 数据。');for(const f of p.files)if(!f.id||!f.kind||!f.originalName)throw Error('项目中存在字段不完整的文件记录。');}
async function openProject(file){try{if(file.size>250*1024*1024)throw Error('项目文件超过 250 MB。');const p=JSON.parse(await file.text());validateProject(p);state.name=p.project?.name||file.name.replace(/\.lsvproj$/i,'');state.createdAt=p.project?.createdAt||new Date().toISOString();state.files=p.files.map(f=>({...f,deletedAt:null}));state.records=p.records||{};state.eis=p.eis||[];state.reaction=p.settings?.reaction||'HER';state.equilibriumPotentialV_RHE=p.settings?.equilibriumPotentialV_RHE??0;state.dirty=false;render();setStatus(`已打开项目 ${state.name}，共 ${state.files.length} 个文件记录。`);}catch(e){setStatus(`打开失败：${e.message}`);}}
function rawRecord(file,text,kind,relativePath){const parts=relativePath.split(/[\\/]/),sampleName=parts.length>1?parts.at(-2):(state.name||'未分组');let sample=state.files.find(f=>f.sampleName===sampleName);return {id:id('file'),sampleId:sample?.sampleId||id('sample'),sampleName,originalName:file.name,relativePath,kind,classification:kind==='lsv'?'raw':kind, testLabel:file.name.replace(/\.[^.]+$/,''),selected:kind==='lsv',...(kind==='lsv'?{}:{rawText:text}),importedAt:new Date().toISOString()};}
async function importFolder(files){let added=0,errors=0;const list=[...files].filter(f=>/\.(txt|csv)$/i.test(f.name));if(!list.length){setStatus('所选文件夹中没有 TXT 或 CSV 文件。');return;}if(!state.name){const first=list[0].webkitRelativePath||list[0].name;state.name=first.split(/[\\/]/)[0]||'LSV项目';state.createdAt=new Date().toISOString();}
 for(const file of list){const relative=file.webkitRelativePath||file.name;if(state.files.some(f=>f.relativePath===relative))continue;const kind=typeFor(file);if(kind==='other')continue;try{if(file.size>20*1024*1024)throw Error('单文件超过 20 MB');const text=await file.text();const rec=rawRecord(file,text,kind,relative);state.files.push(rec);if(kind==='lsv'){try{const rows=parse(text);state.records[rec.id]={parameters:null,rawData:{columns:['potential_V','current_A'],rows},results:null};}catch{rec.kind='processed';rec.classification='unparsed';}}added++;}catch{errors++;}}
 markDirty();render();setStatus(`已导入 ${added} 个文件${errors?`，${errors} 个读取失败`:''}。LSV/ EIS / CV 与已有结果已按名称初步分类，请检查清单。`);}
function computeTargets(data,area,equilibriumPotential=0){return [10,100,1000].map(target=>{const targetDensity=target/area;let hits=[];for(let i=0;i<data.length-1;i++){const a=data[i],b=data[i+1],aa=Math.abs(a.e),bb=Math.abs(b.e);if((targetDensity-aa)*(targetDensity-bb)<=0&&aa!==bb){const t=(targetDensity-aa)/(bb-aa);hits.push(a.f+t*(b.f-a.f));}}const potential=hits.length?hits[0]:null;return {targetCurrent:target,currentUnit:'mA',targetCurrentDensity:targetDensity,currentDensityUnit:'mA/cm^2',potentialAtTargetCurrent:potential,voltageReference:'V vs. RHE',equilibriumPotentialV_RHE:equilibriumPotential,overpotential:potential!==null?Math.abs(potential-equilibriumPotential):null,voltageUnit:'V',status:hits.length?'calculated':'outside-data-range'};});}
function batchProcess(){const params=currentParams(),selected=state.files.filter(f=>!f.deletedAt&&f.kind==='lsv'&&f.selected!==false);if(!selected.length){setStatus('请勾选需要批量处理的原始 LSV 文件。');return;}let done=0,failed=0;for(const f of selected){try{const rec=state.records[f.id];const rows=rec?.rawData?.rows||parse(f.rawText);const result=compute(rows,params.voltage,params.area,params.resistance);state.records[f.id]={parameters:{...params},rawData:{columns:['potential_V','current_A'],rows},results:{lsv:result.data,baseline:result.baseline,baselineIndex:result.index,tafel:result.data.map(r=>[r.t2,r.t1]),overpotentials:computeTargets(result.data,params.area,state.equilibriumPotentialV_RHE)}};done++;}catch{failed++;}}markDirty();render();setStatus(`批量处理完成：${done} 个成功${failed?`，${failed} 个失败`:''}。参数使用当前电压修正、面积和 Rs；10/100/1000 mA 按电流绝对值插值。`);}
function openFile(fileId){const f=state.files.find(x=>x.id===fileId);if(!f)return;if(f.kind==='lsv'){state.currentFileId=fileId;const rec=state.records[fileId];if(rec?.parameters)for(const [key,value] of Object.entries({voltage:rec.parameters.voltage,area:rec.parameters.area,resistance:rec.parameters.resistance}))$(key).value=value;window.dispatchEvent(new CustomEvent('lsv-project-select',{detail:{file:f,record:rec}}));document.getElementById('lsv-page').scrollIntoView({behavior:'smooth'});}else if(f.kind==='eis'){state.currentEisFileId=fileId;const saved=state.eis.find(x=>x.fileId===fileId);window.dispatchEvent(new CustomEvent('lsv-project-open-eis',{detail:{file:f,snapshot:saved?structuredClone(saved):null}}));document.getElementById('eis-page').scrollIntoView({behavior:'smooth'});}else setStatus(`${f.originalName} 已保存在项目中；当前页面暂不分析此文件类型。`);}
function exportOrigin(){const selected=state.files.filter(f=>!f.deletedAt&&f.kind==='lsv'&&f.selected!==false&&state.records[f.id]?.results?.lsv);if(!selected.length)return;const columns=[];for(const f of selected){const record=state.records[f.id],rows=record.results.lsv;columns.push({name:`${f.sampleName} ${f.testLabel} Potential`,unit:'V vs. RHE',comment:'',values:rows.map(r=>r.f)});columns.push({name:`${f.sampleName} ${f.testLabel} Current density`,unit:'mA cm⁻²',comment:`${f.sampleName} / ${f.testLabel}`,values:rows.map(r=>r.e)});}
 const lines=[['Long Name',...columns.map(c=>c.name)],['Units',...columns.map(c=>c.unit)],['Comments',...columns.map(c=>c.comment)]];const n=Math.max(...columns.map(c=>c.values.length));for(let i=0;i<n;i++)lines.push(columns.map(c=>c.values[i]===undefined?'':numberText(c.values[i])));const tsv=lines.map(row=>row.join('\t')).join('\r\n')+'\r\n';download(new Blob(['\uFEFF'+tsv],{type:'text/tab-separated-values;charset=utf-8'}),`${(state.name||'LSV项目').replace(/[\\/:*?"<>|]/g,'_')}_Origin_${dateStamp()}.txt`);}
function exportSummary(){const header=['样品','测试','文件类型','Rs (Ω)','Rct (Ω)','E@10mA (V vs RHE)','ηHER@10mA (V)','状态','E@100mA (V vs RHE)','ηHER@100mA (V)','状态','E@1000mA (V vs RHE)','ηHER@1000mA (V)','状态'];const rows=[header];for(const f of state.files.filter(x=>!x.deletedAt)){const rec=state.records[f.id],eis=state.eis.find(x=>x.fileId===f.id),op=rec?.results?.overpotentials||[];if(f.kind==='lsv')rows.push([f.sampleName,f.testLabel,'LSV',rec?.parameters?.resistance??'', '',... [10,100,1000].flatMap(target=>{const x=op.find(y=>y.targetCurrent===target);return [x?.potentialAtTargetCurrent??'',x?.overpotential??'',x?.status||'未处理'];})]);else if(f.kind==='eis')rows.push([f.sampleName,f.testLabel,'EIS',eis?.selectedResistance?.rs??'',eis?.selectedResistance?.rct??'','','','','','','','','','']);}const csv=rows.map(row=>row.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\r\n')+'\r\n';download(new Blob(['\uFEFF'+csv],{type:'text/csv;charset=utf-8'}),`${(state.name||'LSV项目').replace(/[\\/:*?"<>|]/g,'_')}_结果汇总_${dateStamp()}.csv`);}

$('project-folder').onclick=()=>$('project-folder-input').click();$('project-folder-input').onchange=e=>{importFolder(e.target.files);e.target.value='';};$('project-open').onclick=()=>$('project-open-input').click();$('project-open-input').onchange=e=>{const f=e.target.files[0];e.target.value='';if(f)openProject(f);};$('project-save').onclick=save;$('project-origin').onclick=exportOrigin;$('project-batch').onclick=batchProcess;$('project-summary').onclick=exportSummary;
$('project-select-all').onchange=e=>{state.files.filter(f=>!f.deletedAt&&f.kind==='lsv').forEach(f=>f.selected=e.target.checked);markDirty();render();};
window.addEventListener('lsv-project-eis-state',e=>{const {fileId,snapshot}=e.detail||{};if(!fileId)return;const f=state.files.find(x=>x.id===fileId);if(!f)return;let item=state.eis.find(x=>x.fileId===fileId);if(!item){item={fileId};state.eis.push(item);}Object.assign(item,snapshot);f.eisResult=snapshot?.selectedResistance?.rs!==null&&snapshot?.selectedResistance?.rs!==undefined;render();});
window.addEventListener('lsv-project-eis-opened',e=>{const f=e.detail?.file;if(!f)return;state.currentEisFileId=f.id;});
window.addEventListener('lsv-project-current-eis',e=>{if(state.currentEisFileId)window.dispatchEvent(new CustomEvent('lsv-project-eis-state',{detail:{fileId:state.currentEisFileId,snapshot:e.detail}}));});
window.addEventListener('lsv-project-select',e=>{const {file,record}=e.detail;if(!record?.rawData?.rows)return;const raw=record.rawData.rows;window.dispatchEvent(new CustomEvent('lsv-project-load-lsv',{detail:{file,rows:raw,record}}));});
window.addEventListener('lsv-lsv-processed',e=>{const {rows,parameters,results}=e.detail||{};const fileId=state.currentFileId;if(!fileId)return;state.records[fileId]={parameters,rawData:{columns:['potential_V','current_A'],rows},results:{...results,overpotentials:computeTargets(results.lsv,parameters.area,state.equilibriumPotentialV_RHE)}};markDirty();render();});
window.addEventListener('lsv-file-loaded',e=>{const {file,text,rows}=e.detail||{};if(!file)return;const kind=e.detail.kind||typeFor(file);if(kind==='lsv'){state.name ||=file.name.replace(/\.[^.]+$/,'');state.createdAt ||=new Date().toISOString();let existing=state.files.find(f=>f.originalName===file.name&&f.kind==='lsv');if(!existing){existing=rawRecord(file,text,kind,file.name);state.files.push(existing);}state.records[existing.id]={parameters:null,rawData:{columns:['potential_V','current_A'],rows},results:null};state.currentFileId=existing.id;markDirty();render();}else if(kind==='eis'){state.name ||=file.name.replace(/\.[^.]+$/,'');let existing=state.files.find(f=>f.originalName===file.name&&f.kind==='eis');if(!existing){existing=rawRecord(file,text,kind,file.name);state.files.push(existing);}state.currentEisFileId=existing.id;markDirty();render();}});
setStatus('尚未创建项目。可导入目录，或直接处理单文件后保存项目。');
